select party.party_name as CustomerName,
       c.cust_account_id CustAccountId,
       c.account_name as Description,
       c.account_number as AccountNumber,
       party.party_id PartyId,
       party.JGZZ_FISCAL_CODE TaxRegistration    
from hz_cust_accounts C, 
     hz_parties party
where C.party_id = party.party_id 
and c.cust_account_id in (1000,1001,1002,1003,1004,1005,1006,1007,1008,1021,1146,1148,1150,1256,1287,1289,1290,1292,1398,1438,1288,1318, 103559,114586,115603,71490,103548,103550,114570,100000025664142,100000025664152,100000025664085,100000025664161,3550,
100000010015141,100000010015153,100000010015162,100000010015171,100000010015186,100000010015453,100000010015462,
100000010015471,100000010015480,100000010015489,100000010015498,100000010015507,100000010015516,100000010015525,
100000010015195,100000010015534,100000010015543,100000010015205,100000010015552,100000010015561,100000010015214,
100000010015223,100000010015232
)
order by party.party_name, c.account_number